func evalRPN(_ tokens: [String]) -> Int {
    var stack: [Int] = []
    for t in tokens {
        if let n = Int(t) { stack.append(n); continue }
        let b = stack.removeLast(), a = stack.removeLast()
        switch t {
        case "+": stack.append(a + b)
        case "-": stack.append(a - b)
        case "*": stack.append(a * b)
        default:  stack.append(a / b)
        }
    }
    return stack[0]
}
